if mibBuilder.loadTexts: tmnxOamVccvPingCtlSaiiGlobalId.setReference("RFC 5003, 'Attachment Individual Identifier (AII) Types for\n         Aggregation', Section 3.2, 'AII Type 2'")
if mibBuilder.loadTexts: tmnxOamVccvPingCtlSaiiGlobalId.setStatus('current')
