if mibBuilder.loadTexts: tmnxOamTrCtlTgtAddress.setDescription('The value of tmnxOamTrCtlTgtAddress specifies the destination host\n         address to be used when performing an OAM trace route operation.  The\n         corresponding address type is configured using\n         tmnxOamTrCtlTgtAddrType.')
tmnxOamTrCtlSrcAddrType = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 11, 2, 3, 1, 31), InetAddressType().clone('unknown')).setMaxAccess("readcreate")
if mibBuilder.loadTexts: tmnxOamTrCtlSrcAddrType.setStatus('current')
