tmnxOamTrResultsTestAttempts = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 11, 2, 4, 1, 5), Unsigned32()).setUnits('tests').setMaxAccess("readonly")
