if mibBuilder.loadTexts: tmnxOamSaaCtlFailures.setStatus('current')
if mibBuilder.loadTexts: tmnxOamSaaCtlFailures.setDescription('The value of tmnxOamSaaCtlFailures indicates the number of times this\n         SAA test has failed.')
tmnxOamSaaCtlLastRunResult = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 11, 3, 2, 1, 11), TmnxOamTestResult()).setMaxAccess("readonly")
