tmnxOamSysPerfCfgLspSelfTxLimit = MibScalar((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 11, 5, 2, 14), Gauge32()).setUnits('echo request packets per second').setMaxAccess("readonly")
